import{mixedState}from'../qa/mixed-states.mjs';
import fs from'node:fs';import crypto from'node:crypto';import assert from'node:assert/strict';import{createCommon}from'../create-common.mjs';import{defaultState}from'../src/State.mjs';
const m=createCommon({headDriver:true}),sha=x=>crypto.createHash('sha256').update(x).digest('hex'),rows=[],positionReference=m.positions,indexReference=m.faces,started=performance.now();
for(const rig of['anny','mhr'])for(const headRig of['gnm','body'])for(const headShape of['gnm','anny','mhr'])for(const expression of['gnm','anny','mhr'])for(const gaze of['gnm','rig','expression']){
 const s=mixedState({rig,headRig,headShape,expression,gaze},m.mhrMeta);
 const v=m.compute(s).slice(),hash=sha(v),archive=JSON.parse(JSON.stringify(m.archive()));assert(v.every(Number.isFinite));assert.equal(m.positions,positionReference);assert.equal(m.faces,indexReference);
 const inactive=structuredClone(s);if(rig==='anny'){inactive.mhr.pose[46]=.2;inactive.mhr.correctives=false;}else inactive.anny.pose['upperarm01.L']=[-20,15,30];if(expression!=='gnm')inactive.gnm.expression[200]=-.3;if(expression!=='anny')inactive.anny.facialActions.jawOpen=.8;if(expression!=='mhr')inactive.mhr.expression[m.mhrMeta.expression_names.indexOf('jawDrop')]=.8;if(headShape!=='gnm')inactive.gnm.identity[0]=-.4;if(headShape!=='anny')inactive.anny.localChanges['nose-width1-incr']=-.4;if(gaze!=='gnm')inactive.gnm.rotation[6]=-.2;if(gaze!=='expression'){inactive.anny.facialActions.eyeLookDownLeft=.8;inactive.mhr.expression[14]=.8;}if(headRig!=='gnm'){inactive.gnm.rotation[1]=-.2;inactive.gnm.translation=[.02,.01,.01];}
 assert.equal(sha(m.compute(inactive)),hash,'Inactive leak: '+JSON.stringify(s.owners));m.compute(defaultState());m.restore(archive);assert.equal(sha(m.positions),hash,'Archive mismatch');m.compute({...s,owners:{...s.owners,rig:rig==='anny'?'mhr':'anny'}});assert.equal(sha(m.compute(s)),hash,'Switch-back mismatch');rows.push({owners:s.owners,sha256:hash,metrics:m.metrics(),inactiveSourceExact:true,archiveAndSwitchBackExact:true});if(rows.length%18===0)console.log('mixed source states',rows.length);
}
fs.writeFileSync(new URL('../research/mixed-source-grid-report.json',import.meta.url),JSON.stringify({passed:true,fingerprint:m.adapterFingerprint,cases:rows.length,elapsedSeconds:(performance.now()-started)/1000,rows,numericalOnly:true,visualAcceptance:false},null,2));console.log({passed:true,cases:rows.length});
